            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                sources.setdefault(c, []).append((r, color))

    # Each gap sends its color upward; a higher source takes over above it.
    for c, entries in sources.items():
        entries.sort()
        for i, (r, color) in enumerate(entries):
            top = entries[i - 1][0] + 1 if i > 0 else 0
            for rr in range(top, r + 1):
                if grid[rr][c] == 0 or rr == r:
                    out[rr][c] = color

